def el_konumu(t):
    # 0-0.4 s: 0.8 m/s sabit hiz; sonra 4 m/s^2 ile yavaslayip 0.6 s'de durur
    if t <= 0.4:
        return 0.8 * t
    if t <= 0.6:
        d = t - 0.4
        return 0.32 + 0.8 * d - 2.0 * d * d
    return 0.4

def el_hizi(t):
    if t <= 0.4:
        return 0.8
    if t <= 0.6:
        return 0.8 - 4.0 * (t - 0.4)
    return 0.0

