def dirsek_acisi(ust_kol, on_kol, omuz_el):
    c = (ust_kol ** 2 + on_kol ** 2 - omuz_el ** 2) / (2 * ust_kol * on_kol)
    c = max(-1.0, min(1.0, c))
    return round(math.degrees(math.acos(c)), 2)

