import math

def sabine(V, yuzeyler):
    A = sum(S * a for S, a in yuzeyler)
    return A, 0.161 * V / A

def eyring(V, yuzeyler):
    S = sum(s for s, _ in yuzeyler)
    ort = sum(s * a for s, a in yuzeyler) / S
    return 0.161 * V / (-S * math.log(1 - ort))

