def goruntu_kaynak(n):
    say = 0
    for i in range(-n, n + 1):
        for j in range(-n, n + 1):
            k = n - abs(i) - abs(j)
            if k == 0:
                say += 1
            elif k > 0:
                say += 2
    return say

