import math

KOSE_BAYT = 12 + 12 + 8      # konum + normal + uv
INDIS_BAYT = 3 * 4           # ucgen basina 3 adet uint32

def ag_mb(ucgen):
    kose = ucgen // 2         # kapali, manifold ag icin V ~ F/2 (Euler)
    return round((kose * KOSE_BAYT + ucgen * INDIS_BAYT) / 1e6, 2)

